sys_script_include.script:
var TimeTableRefQual = Class.create();
TimeTableRefQual.prototype = {

    initialize: function() {},

    // --------------------------------------------------
    // 1. SECTION REFERENCE QUALIFIER
    // --------------------------------------------------
    // Filters sections using the selected semester's
    // college, program and academic year.
    // --------------------------------------------------

    getSections: function(current) {

        var noRecords = 'sys_id=-1';

        if (!current) {
            return noRecords;
        }

        var semesterId = current.getValue('semester');

        if (!semesterId) {
            return noRecords;
        }

        // Retrieve selected semester
        var semesterGR = new GlideRecord(
            'x_1790229_edusph_0_semester'
        );

        if (!semesterGR.get(semesterId)) {
            return noRecords;
        }

        var collegeId = semesterGR.getValue('college');
        var programId = semesterGR.getValue('program');
        var academicYearId = semesterGR.getValue('year');

        // College and Program are required for filtering
        if (!collegeId || !programId) {
            return noRecords;
        }

        // Find matching sections
        var sectionGR = new GlideRecord(
            'x_1790229_edusph_0_section'
        );

        sectionGR.addQuery('college', collegeId);
        sectionGR.addQuery('program', programId);

        // Match academic year when available
        if (academicYearId) {
            sectionGR.addQuery('year', academicYearId);
        }

        sectionGR.query();

        var sectionIds = [];

        while (sectionGR.next()) {
            sectionIds.push(sectionGR.getUniqueValue());
        }

        if (sectionIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + sectionIds.join(',');
    },


    // --------------------------------------------------
    // 2. SEMESTER REFERENCE QUALIFIER
    // --------------------------------------------------
    // Filters semesters belonging to the active
    // academic year.
    // If a section is selected, also matches its
    // college, program and academic year.
    // --------------------------------------------------

    getSemesters: function(current) {

        var noRecords = 'sys_id=-1';

        // Retrieve active academic years
        var academicYearGR = new GlideRecord(
            'x_1790229_edusph_0_academic_year'
        );

        academicYearGR.addQuery('active', true);
        academicYearGR.query();

        var academicYearIds = [];

        while (academicYearGR.next()) {
            academicYearIds.push(
                academicYearGR.getUniqueValue()
            );
        }

        if (academicYearIds.length === 0) {
            return noRecords;
        }

        // Start filtering semesters by active academic year
        var semesterGR = new GlideRecord(
            'x_1790229_edusph_0_semester'
        );

        semesterGR.addQuery(
            'year',
            'IN',
            academicYearIds.join(',')
        );

        // If a section has already been selected,
        // further restrict semesters using its details.
        var sectionId = current ?
            current.getValue('section') : '';

        if (sectionId) {

            var sectionGR = new GlideRecord(
                'x_1790229_edusph_0_section'
            );

            if (!sectionGR.get(sectionId)) {
                return noRecords;
            }

            var collegeId = sectionGR.getValue('college');
            var programId = sectionGR.getValue('program');
            var academicYearId = sectionGR.getValue('year');

            if (collegeId) {
                semesterGR.addQuery('college', collegeId);
            }

            if (programId) {
                semesterGR.addQuery('program', programId);
            }

            if (academicYearId) {
                semesterGR.addQuery('year', academicYearId);
            }
        }

        semesterGR.query();

        var semesterIds = [];

        while (semesterGR.next()) {
            semesterIds.push(
                semesterGR.getUniqueValue()
            );
        }

        if (semesterIds.length === 0) {
            return noRecords;
        }

        return 'sys_idIN' + semesterIds.join(',');
    },

        getLabBatchesForTimetableEntry: function(current) {
        if (!current) return 'sys_id=-1';
        var timetableId = current.getValue('timetable');
        if (!timetableId) return 'sys_id=-1';
        var ttGR = new GlideRecord('x_1790229_edusph_0_timetable');
        if (ttGR.get(timetableId)) {
            var sectionId = ttGR.getValue('section');
            if (sectionId) {
                return 'section=' + sectionId;
            }
        }
        return 'sys_id=-1';
    },

    type: 'TimeTableRefQual'
};
